import { create } from 'zustand'
import { persist } from 'zustand/middleware'
import type { Category, Contact, Draft, ReplyMode } from '../types'
import { useMail } from './mail'
import { uid } from '../lib/id'
import { textToHtml } from '../lib/html'

export interface ComposeWin {
  id: string // draft id
  minimized: boolean
  maximized: boolean
}

export interface Toast {
  id: number
  message: string
  action?: { label: string; run: () => void }
  secondary?: { label: string; run: () => void }
  duration: number
}

export type Overlay = null | 'settings' | 'shortcuts' | 'newLabel' | 'advancedSearch'

interface UIState {
  selected: string[]
  composes: ComposeWin[]
  inboxTab: Category
  drawerOpen: boolean
  overlay: Overlay
  toast: Toast | null
  focusIndex: number
  labelEdit: string | null
  preview: { threadId: string; messageId: string; attachmentId: string } | null

  setSelected: (ids: string[]) => void
  toggleSelected: (id: string) => void
  clearSelection: () => void
  setInboxTab: (c: Category) => void
  setDrawer: (open: boolean) => void
  setOverlay: (o: Overlay) => void
  setFocusIndex: (i: number) => void
  setLabelEdit: (id: string | null) => void
  setPreview: (p: UIState['preview']) => void

  openCompose: (draft?: Partial<Draft>) => string
  openDraft: (id: string) => void
  closeCompose: (id: string) => void
  updateCompose: (id: string, p: Partial<ComposeWin>) => void

  showToast: (message: string, opts?: Partial<Omit<Toast, 'id' | 'message'>>) => void
  hideToast: () => void
}

let toastSeq = 0

export function signatureHtml() {
  const sig = useMail.getState().settings.signature.trim()
  return sig ? `<p><br></p><div class="signature" style="color:var(--muted)">--<br>${textToHtml(sig).replace(/^<p>|<\/p>$/g, '')}</div>` : ''
}

export function newDraft(p: Partial<Draft> = {}): Draft {
  return {
    id: uid('d'),
    to: [],
    cc: [],
    bcc: [],
    subject: '',
    html: '<p><br></p>' + signatureHtml(),
    attachments: [],
    updatedAt: Date.now(),
    ...p,
  }
}

export const useUI = create<UIState>()(
  persist(
    (set, get) => ({
      selected: [],
      composes: [],
      inboxTab: 'primary',
      drawerOpen: false,
      overlay: null,
      toast: null,
      focusIndex: 0,
      labelEdit: null,
      preview: null,

      setSelected: (ids) => set({ selected: ids }),
      toggleSelected: (id) => {
        const s = get().selected
        set({ selected: s.includes(id) ? s.filter((x) => x !== id) : [...s, id] })
      },
      clearSelection: () => set({ selected: [] }),
      setInboxTab: (c) => set({ inboxTab: c, selected: [], focusIndex: 0 }),
      setDrawer: (open) => set({ drawerOpen: open }),
      setOverlay: (o) => set({ overlay: o }),
      setFocusIndex: (i) => set({ focusIndex: i }),
      setLabelEdit: (id) => set({ labelEdit: id }),
      setPreview: (p) => set({ preview: p }),

      openCompose: (p) => {
        const draft = newDraft(p)
        useMail.getState().saveDraft(draft)
        const composes = get().composes.map((c) => ({ ...c, maximized: false }))
        // Gmail keeps a limited number of windows open
        const trimmed = composes.length >= 3 ? composes.slice(1) : composes
        set({ composes: [...trimmed, { id: draft.id, minimized: false, maximized: false }] })
        return draft.id
      },
      openDraft: (id) => {
        const existing = get().composes.find((c) => c.id === id)
        if (existing) {
          set({ composes: get().composes.map((c) => (c.id === id ? { ...c, minimized: false } : c)) })
          return
        }
        const composes = get().composes
        const trimmed = composes.length >= 3 ? composes.slice(1) : composes
        set({ composes: [...trimmed, { id, minimized: false, maximized: false }] })
      },
      closeCompose: (id) => set({ composes: get().composes.filter((c) => c.id !== id) }),
      updateCompose: (id, p) => set({ composes: get().composes.map((c) => (c.id === id ? { ...c, ...p } : c)) }),

      showToast: (message, opts) => set({ toast: { id: ++toastSeq, message, duration: opts?.duration ?? 6000, ...opts } }),
      hideToast: () => set({ toast: null }),
    }),
    {
      name: 'opus-mail-ui-v1',
      partialize: (s) => ({ composes: s.composes, inboxTab: s.inboxTab }),
    },
  ),
)

/** Build a reply / forward draft for a thread and open it inline or in a window */
export function buildReplyDraft(threadId: string, mode: ReplyMode, messageId?: string): Draft {
  const mail = useMail.getState()
  const t = mail.threads[threadId]
  const msg = (messageId && t.messages.find((m) => m.id === messageId)) || t.messages[t.messages.length - 1]
  const me = 'sam.rivera@lumenlabs.io'
  const lastFromOther = [...t.messages].reverse().find((m) => m.from.email !== me) ?? msg
  let to: Contact[] = []
  let cc: Contact[] = []
  if (mode === 'reply') {
    to = msg.from.email === me ? msg.to : [msg.from]
  } else if (mode === 'replyAll') {
    const base = msg.from.email === me ? lastFromOther : msg
    const all = [base.from, ...base.to, ...base.cc]
    const seen = new Set<string>()
    const uniq = all.filter((c) => c.email !== me && !seen.has(c.email) && (seen.add(c.email), true))
    to = uniq.slice(0, 1)
    cc = uniq.slice(1)
  }
  const date = new Date(msg.date).toLocaleString([], { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' })
  const quote =
    mode === 'forward'
      ? `<p><br></p>${signatureHtml()}<p><br></p><div class="quote">---------- Forwarded message ---------<br>From: <b>${msg.from.name}</b> &lt;${msg.from.email}&gt;<br>Date: ${date}<br>Subject: ${t.subject}<br>To: ${msg.to.map((c) => c.name).join(', ')}<br><br>${msg.html}</div>`
      : `<p><br></p>${signatureHtml()}<p><br></p><blockquote class="quote">On ${date} ${msg.from.name} &lt;${msg.from.email}&gt; wrote:<br>${msg.html}</blockquote>`
  const subject = mode === 'forward' ? (t.subject.startsWith('Fwd:') ? t.subject : `Fwd: ${t.subject}`) : t.subject.startsWith('Re:') ? t.subject : `Re: ${t.subject}`
  return newDraft({
    to,
    cc,
    subject,
    html: quote,
    threadId,
    replyMode: mode,
    attachments: mode === 'forward' ? msg.attachments : [],
  })
}

import { useEffect, useMemo, useState } from 'react'
import { useMail } from './store/mail'
import { useUI } from './store/ui'
import type { Category, FolderId, Thread, View } from './types'
import { inFolder, isSnoozed, lastDate, lastSentDate } from './lib/mail'
import { matchThread, parseQuery } from './lib/search'

export function useNow(interval = 30_000) {
  const [now, setNow] = useState(() => Date.now())
  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), interval)
    return () => clearInterval(id)
  }, [interval])
  return now
}

export function useViewThreads(view: View): Thread[] {
  const threads = useMail((s) => s.threads)
  const labels = useMail((s) => s.labels)
  const categories = useMail((s) => s.settings.categories)
  const tab = useUI((s) => s.inboxTab)
  const now = useNow()
  return useMemo(() => {
    const all = Object.values(threads)
    let list: Thread[]
    let sortKey = lastDate
    if (view.kind === 'folder') {
      list = all.filter((t) => inFolder(t, view.folder, now, categories, tab))
      if (view.folder === 'sent') sortKey = lastSentDate
      if (view.folder === 'snoozed') sortKey = (t) => -(t.snoozeUntil ?? 0)
    } else if (view.kind === 'label') {
      list = all.filter((t) => t.labels.includes(view.labelId) && !t.trash && !t.spam)
    } else {
      const q = parseQuery(view.query)
      list = all.filter((t) => matchThread(t, q, labels, now))
    }
    return list.sort((a, b) => sortKey(b) - sortKey(a))
  }, [threads, labels, view, now, categories, tab])
}

export function useCounts() {
  const threads = useMail((s) => s.threads)
  const drafts = useMail((s) => s.drafts)
  const outbox = useMail((s) => s.outbox)
  const labels = useMail((s) => s.labels)
  const categories = useMail((s) => s.settings.categories)
  const now = useNow()
  return useMemo(() => {
    const all = Object.values(threads)
    const unreadIn = (f: FolderId) => all.filter((t) => t.unread && inFolder(t, f, now, false)).length
    const inboxUnread = all.filter((t) => t.unread && inFolder(t, 'inbox', now, categories, 'primary')).length
    const cat: Record<Category, number> = { primary: 0, promotions: 0, social: 0, updates: 0 }
    const catNew: Record<Category, { count: number; from: string[] }> = {
      primary: { count: 0, from: [] },
      promotions: { count: 0, from: [] },
      social: { count: 0, from: [] },
      updates: { count: 0, from: [] },
    }
    for (const t of all) {
      if (t.unread && inFolder(t, 'inbox', now, false)) {
        cat[t.category]++
        catNew[t.category].count++
        const n = t.messages[t.messages.length - 1].from.name
        if (!catNew[t.category].from.includes(n)) catNew[t.category].from.push(n)
      }
    }
    const byLabel: Record<string, number> = {}
    for (const l of labels) byLabel[l.id] = all.filter((t) => t.unread && t.labels.includes(l.id) && !t.trash && !t.spam).length
    return {
      inbox: inboxUnread,
      spam: unreadIn('spam'),
      snoozed: all.filter((t) => isSnoozed(t, now) && !t.trash).length,
      drafts: Object.keys(drafts).length,
      scheduled: Object.values(outbox).filter((d) => d.scheduled).length,
      important: unreadIn('important'),
      byLabel,
      catNew,
    }
  }, [threads, drafts, outbox, labels, categories, now])
}

import { useSyncExternalStore } from 'react'
import type { View } from '../types'
import { parseHash, viewToHash } from './mail'

function subscribe(cb: () => void) {
  window.addEventListener('hashchange', cb)
  return () => window.removeEventListener('hashchange', cb)
}

export function useHash() {
  return useSyncExternalStore(subscribe, () => window.location.hash, () => '')
}

export function useRoute() {
  const hash = useHash()
  return parseHash(hash)
}

export function navigate(hash: string, replace = false) {
  if (replace) {
    const url = new URL(window.location.href)
    url.hash = hash
    window.history.replaceState(null, '', url)
    window.dispatchEvent(new HashChangeEvent('hashchange'))
  } else if (window.location.hash !== hash) {
    window.location.hash = hash
  }
}

export function goView(v: View, threadId?: string, replace = false) {
  navigate(viewToHash(v, threadId), replace)
}

import { useMail } from './store/mail'
import { useUI } from './store/ui'
import { formatScheduleLabel } from './lib/format'

const mail = () => useMail.getState()
const ui = () => useUI.getState()

function noun(n: number) {
  return n === 1 ? 'Conversation' : `${n} conversations`
}

function toastUndo(message: string) {
  ui().showToast(message, {
    action: {
      label: 'Undo',
      run: () => {
        if (mail().undo()) ui().showToast('Action undone', { duration: 3000 })
      },
    },
  })
}

export const actions = {
  archive(ids: string[]) {
    if (!ids.length) return
    mail().archive(ids)
    toastUndo(`${noun(ids.length)} archived.`)
  },
  moveToInbox(ids: string[]) {
    if (!ids.length) return
    mail().moveToInbox(ids)
    toastUndo(`${noun(ids.length)} moved to Inbox.`)
  },
  trash(ids: string[]) {
    if (!ids.length) return
    mail().trash(ids)
    toastUndo(`${noun(ids.length)} moved to Trash.`)
  },
  deleteForever(ids: string[]) {
    if (!ids.length) return
    mail().deleteForever(ids)
    toastUndo(`${noun(ids.length)} deleted forever.`)
  },
  spam(ids: string[]) {
    if (!ids.length) return
    mail().setSpam(ids, true)
    toastUndo(`${noun(ids.length)} marked as spam.`)
  },
  notSpam(ids: string[]) {
    if (!ids.length) return
    mail().setSpam(ids, false)
    toastUndo(`${noun(ids.length)} moved to Inbox.`)
  },
  read(ids: string[], unread: boolean) {
    if (!ids.length) return
    mail().setUnread(ids, unread)
    if (ids.length > 1) toastUndo(`${noun(ids.length)} marked as ${unread ? 'unread' : 'read'}.`)
  },
  star(ids: string[], starred: boolean) {
    if (!ids.length) return
    mail().setStar(ids, starred)
    if (ids.length > 1) toastUndo(`${noun(ids.length)} ${starred ? 'starred' : 'unstarred'}.`)
  },
  important(ids: string[], important: boolean) {
    if (!ids.length) return
    mail().setImportant(ids, important)
    toastUndo(`${noun(ids.length)} marked as ${important ? '' : 'not '}important.`)
  },
  snooze(ids: string[], until: number) {
    if (!ids.length) return
    mail().snooze(ids, until)
    toastUndo(`Snoozed until ${formatScheduleLabel(until)}`)
  },
  unsnooze(ids: string[]) {
    mail().unsnooze(ids)
    toastUndo(`${noun(ids.length)} unsnoozed.`)
  },
  label(ids: string[], labelId: string, on: boolean) {
    if (!ids.length) return
    const l = mail().labels.find((x) => x.id === labelId)
    if (on) mail().addLabel(ids, labelId)
    else mail().removeLabel(ids, labelId)
    toastUndo(`${noun(ids.length)} ${on ? 'added to' : 'removed from'} "${l?.name}".`)
  },
  moveTo(ids: string[], labelId: string) {
    if (!ids.length) return
    const l = mail().labels.find((x) => x.id === labelId)
    mail().moveToLabel(ids, labelId)
    toastUndo(`${noun(ids.length)} moved to "${l?.name}".`)
  },
}

