  const msg = (messageId && t.messages.find((m) => m.id === messageId)) || t.messages[t.messages.length - 1]
  const me = 'sam.rivera@lumenlabs.io'
  const lastFromOther = [...t.messages].reverse().find((m) => m.from.email !== me) ?? msg
  let to: Contact[] = []
  let cc: Contact[] = []
  if (mode === 'reply') {
