              type="button"
              onClick={() => {
                close()
                if (confirm('Reset the mailbox to its original demo state? Your local changes will be lost.')) {
                  reset()
                  useUI.getState().setSelected([])
                  goView({ kind: 'folder', folder: 'inbox' })
                  useUI.getState().showToast('Mailbox restored to demo data.')
