                    else useUI.getState().showToast('No unread conversations here.')
                  }}
                >
                  Mark all as read
                </MenuItem>
                <MenuItem
                  icon={<Star size={16} />}
                  onClick={() => {
                    close()
                    setSelected(pageItems.filter((t) => t.starred).map((t) => t.id))
