                  <X size={17} />
                </IconButton>
              </div>
            )
          }
          return (
            <div key={c.id} className="animate-slide-up pointer-events-auto flex h-[min(620px,calc(100vh-80px))] w-[min(560px,calc(100vw-32px))] flex-col rounded-t-xl bg-surface shadow-pop">
