              aria-label={`Remove ${c.email}`}
              onClick={(e) => {
                e.stopPropagation()
                onChange(value.filter((_, j) => j !== i))
              }}
              className="flex h-4 w-4 items-center justify-center rounded-full text-muted hover:bg-hover-strong"
            >
              <X size={12} />
            </button>
          </span>
        ))}
