    useMail.getState().saveDraft(d)
    if (replyId && drafts[replyId]) {
      const old = drafts[replyId]
      if (!stripHtml(old.html.split('<blockquote')[0]).replace(/--.*/, '').trim()) useMail.getState().discardDraft(replyId)
    }
    if (mobile) {
      useUI.getState().openDraft(d.id)
      return
    }
