@import 'tailwindcss';

@custom-variant dark (&:where([data-theme='dark'], [data-theme='dark'] *));

:root {
  --bg: #f6f8fc;
  --surface: #ffffff;
  --surface-2: #f2f6fc;
  --hover: rgba(68, 71, 70, 0.08);
  --hover-strong: rgba(68, 71, 70, 0.14);
  --active: #d3e3fd;
  --compose: #c2e7ff;
  --on-compose: #001d35;
  --ink: #1f1f1f;
  --muted: #5f6368;
  --line: #e3e7ec;
  --line-strong: #c4c7c5;
  --accent: #0b57d0;
  --on-accent: #ffffff;
  --select: #c2dbff;
  --star: #f4b400;
  --danger: #d93025;
  --code-bg: #f1f3f4;
  --search: #e9eef6;
  --row-unread: #ffffff;
  --row-read: #f2f6fc;
  --tip: #3c4043;
  --shadow-pop: 0 4px 8px 3px rgba(60, 64, 67, 0.15), 0 1px 3px rgba(60, 64, 67, 0.3);
  --shadow-row: inset 1px 0 0 #dadce0, inset -1px 0 0 #dadce0, 0 1px 2px 0 rgba(60, 64, 67, 0.3), 0 1px 3px 1px rgba(60, 64, 67, 0.15);
  color-scheme: light;
}

[data-theme='dark'] {
  --bg: #111214;
  --surface: #1e1f22;
  --surface-2: #1a1b1e;
  --hover: rgba(232, 234, 237, 0.08);
  --hover-strong: rgba(232, 234, 237, 0.14);
  --active: #004a77;
  --compose: #004a77;
  --on-compose: #c2e7ff;
  --ink: #e3e3e3;
  --muted: #a9acb0;
  --line: #34363a;
  --line-strong: #5f6368;
  --accent: #a8c7fa;
  --on-accent: #062e6f;
  --select: #2c3d57;
  --star: #fdd663;
  --danger: #f28b82;
  --code-bg: #2a2b2e;
  --search: #2a2b2f;
  --row-unread: #1e1f22;
  --row-read: #18191b;
  --tip: #e3e3e3;
  --shadow-pop: 0 4px 12px 3px rgba(0, 0, 0, 0.5), 0 1px 3px rgba(0, 0, 0, 0.6);
  --shadow-row: inset 1px 0 0 #3c4043, inset -1px 0 0 #3c4043, 0 1px 3px 1px rgba(0, 0, 0, 0.5);
  color-scheme: dark;
}

@theme inline {
  --color-bg: var(--bg);
  --color-surface: var(--surface);
  --color-surface-2: var(--surface-2);
  --color-hover: var(--hover);
  --color-hover-strong: var(--hover-strong);
  --color-active: var(--active);
  --color-compose: var(--compose);
  --color-on-compose: var(--on-compose);
  --color-ink: var(--ink);
  --color-muted: var(--muted);
  --color-line: var(--line);
  --color-line-strong: var(--line-strong);
  --color-accent: var(--accent);
  --color-on-accent: var(--on-accent);
  --color-select: var(--select);
  --color-star: var(--star);
  --color-danger: var(--danger);
  --color-search: var(--search);
  --color-row-unread: var(--row-unread);
  --color-row-read: var(--row-read);
  --shadow-pop: var(--shadow-pop);
  --shadow-row: var(--shadow-row);
  --font-sans: 'Google Sans Text', 'Google Sans', Roboto, 'Segoe UI', system-ui, -apple-system, 'Helvetica Neue', Arial, sans-serif;
  --animate-pop: pop 0.14s cubic-bezier(0.2, 0, 0, 1);
  --animate-fade: fade 0.15s ease-out;
  --animate-slide-up: slideUp 0.22s cubic-bezier(0.2, 0, 0, 1);
  --animate-slide-in: slideIn 0.22s cubic-bezier(0.2, 0, 0, 1);
}

@keyframes pop {
  from { opacity: 0; transform: scale(0.97) translateY(-4px); }
  to { opacity: 1; transform: none; }
}
@keyframes fade {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes slideUp {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: none; }
}
@keyframes slideIn {
  from { transform: translateX(-100%); }
  to { transform: none; }
}

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-sans);
  font-size: 14px;
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}

button {
  cursor: pointer;
}

::selection {
  background: color-mix(in srgb, var(--accent) 30%, transparent);
}

/* scrollbars */
.scroll-thin {
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--muted) 45%, transparent) transparent;
}

/* tooltips */
[data-tip] {
  position: relative;
}
@media (hover: hover) {
  [data-tip]:hover::after {
    content: attr(data-tip);
    position: absolute;
    left: 50%;
    top: calc(100% + 4px);
    transform: translateX(-50%);
    background: var(--tip);
    color: var(--surface);
    font-size: 12px;
    font-weight: 500;
    line-height: 1;
    padding: 6px 8px;
    border-radius: 4px;
    white-space: nowrap;
    pointer-events: none;
    z-index: 70;
    animation: fade 0.1s ease-out 0.45s both;
  }
  [data-tip][data-tip-pos='above']:hover::after {
    top: auto;
    bottom: calc(100% + 4px);
  }
}

/* message body */
.mail-body {
  font-size: 14px;
  line-height: 1.55;
  overflow-wrap: anywhere;
}
.mail-body p {
  margin: 0 0 0.85em;
}
.mail-body ul,
.mail-body ol {
  margin: 0 0 0.85em;
  padding-left: 1.6em;
}
.mail-body ul { list-style: disc; }
.mail-body ol { list-style: decimal; }
.mail-body li { margin: 0.2em 0; }
.mail-body a {
  color: var(--accent);
  text-decoration: underline;
}
.mail-body h1, .mail-body h2, .mail-body h3 {
  font-size: 1.35em;
  font-weight: 500;
  margin: 0 0 0.5em;
}
.mail-body blockquote {
  border-left: 2px solid var(--line-strong);
  margin: 0 0 0.8em;
  padding-left: 12px;
  color: var(--muted);
}
.mail-body code {
  background: var(--code-bg);
  padding: 1px 4px;
  border-radius: 4px;
  font-size: 0.92em;
}
.mail-body td { padding: 2px 12px 2px 0; }
.mail-body img { max-width: 100%; }

.editor:empty::before,
.editor.is-empty::before {
  content: attr(data-placeholder);
  color: var(--muted);
  pointer-events: none;
  position: absolute;
}
.editor:focus {
  outline: none;
}
.editor .quote {
  color: var(--muted);
}

mark.hl {
  background: color-mix(in srgb, #fbbc04 45%, transparent);
  color: inherit;
  border-radius: 2px;
}

@media print {
  .no-print { display: none !important; }
}

