  trigger: (props: { open: boolean; toggle: () => void }) => ReactNode
  children: (close: () => void) => ReactNode
  align?: 'left' | 'right'
  width?: number
  open?: boolean
  onOpenChange?: (o: boolean) => void
  className?: string
}

